pub fn mul_vec3(self, rhs: DVec3) -> DVec3 {
    glam_assert!(self.is_normalized());

    let w = self.w;
    let b = DVec3::new(self.x, self.y, self.z);
    let b2 = b.dot(b);
    rhs.mul(w * w - b2)
        .add(b.mul(rhs.dot(b) * 2.0))
        .add(b.cross(rhs).mul(w * 2.0))
}

